type Subject = { id:number; code:string; name:string; active:boolean; tree_version:number; review_questions:number }
type Question = { id:number; paper_id:number; number:string; text:string; marks:number|null; structure:any; unit:number|null; topic_ids:string[]; confirmed:boolean; revision:number }
type BankResult = Question & { paper_title:string; paper_year:number|null; similarity?:number; matched_part?:string }
type Paper = { id:number; subject_id:number; title:string; year:number|null; status:string; archived:boolean; filename:string|null; generated?:boolean; generation?:any; questions:Question[] }
type Result = { id:number; target:Question; reference:Question; label:string; reason:string; evidence:any[]; source:string; stale:boolean }
type Comparison = { id:number; subject_id:number; title:string; target_ids:number[]; reference_ids:number[]; rerun_of_id?:number|null; status:string; progress:number; total:number; error:string|null; job?:{id:number;status:string;progress:number;total:number;error:string|null}|null; results?:Result[] }
type ComparisonActivity = { id:number; comparison_id:number; target_id:number; reference_id:number; agent:string; event:string; payload:Record<string,any>; created_at:string }
type Template = { id:number; kind:string; name:string; subject_id:number|null; definition:Record<string,unknown>; version:number }
type Material = { id:number; subject_id:number; filename:string; warnings:string[]; pages:number; proposals:Record<string,any>; enrichment?:{status?:string;progress?:number;total?:number;error?:string|null;tree_version?:number;sections_processed?:number;unmapped_sections?:number;potential_conflict_count?:number} }
type SyllabusStatus = { id:number; filename:string; subject_id:number|null; status:string; error:string|null; warnings:string[]; job?:{id:number;status:string;progress:number;total:number;error:string|null}|null }
type TreeRevision = { id:number; version:number; reason:string; created_at:string }
type Message = { id:number; role:'assistant'|'user'; text:string; card?:'compare'|'export'|'report'|'generate'|'upload'|'new-paper'; file_url?:string|null; tool_trace?:any[]; activity?:Activity[]; streaming?:boolean; reveal?:boolean; upload?:any; view?:View }
type View = 'chat'|'papers'|'knowledge'|'materials'|'templates'|'reports'|'users'|'models'|'operations'
type WorkspaceUser = { id:number; email:string|null; display_name:string; role:'admin'|'teacher'; subject_ids:number[]; active:boolean }

function ComparePaperDialog({papers,templates,baseId,comparisonIds,patternId,preview,issue,busy,onBase,onToggle,onPattern,onClose,onPreview,onRun}:{papers:Paper[];templates:Template[];baseId:number|null;comparisonIds:number[];patternId:number|null;preview:any;issue:string;busy:boolean;onBase:(id:number|null)=>void;onToggle:(id:number)=>void;onPattern:(id:number|null)=>void;onClose:()=>void;onPreview:()=>void;onRun:()=>void}) {
  const patterns=templates.filter(item=>item.kind==='comparison'&&(item.definition as any)?.question_pattern?.units?.length)
  const comparisonPapers=papers.filter(paper=>paper.status==='reference'&&!paper.archived&&paper.id!==baseId)
  const base=papers.find(item=>item.id===baseId)
  return <div className="compare-picker-backdrop" onMouseDown={event=>{if(event.target===event.currentTarget)onClose()}}><section className="compare-picker" role="dialog" aria-modal="true" aria-labelledby="compare-picker-title"><header><div><h2 id="compare-picker-title">Compare papers</h2><p>Choose one Base paper, a question pattern, and one or more comparison papers.</p></div><button className="icon-button" aria-label="Close paper comparison picker" onClick={onClose}><X size={18}/></button></header>
    <label className="compare-base-select">Base paper<select value={baseId??''} onChange={event=>onBase(Number(event.target.value)||null)}><option value="">Select Base paper</option>{papers.filter(paper=>!paper.archived).map(paper=><option key={paper.id} value={paper.id}>{paper.title}{paper.year?` · ${paper.year}`:''}</option>)}</select></label>
    <label className="compare-base-select">Question pattern<select value={patternId??''} onChange={event=>onPattern(Number(event.target.value)||null)}><option value="">Select question pattern</option>{patterns.map(pattern=><option key={pattern.id} value={pattern.id}>{pattern.name}</option>)}</select><small>Maps question labels to units for this run. Saved question tags are unchanged.</small></label>
    <div className="compare-reference-select"><strong>Comparison papers <small>Select all that apply</small></strong>{comparisonPapers.length?comparisonPapers.map(paper=><label key={paper.id}><input type="checkbox" checked={comparisonIds.includes(paper.id)} onChange={()=>onToggle(paper.id)}/><span>{paper.title}{paper.year?` · ${paper.year}`:''}<small>{paper.questions.length} extracted questions</small></span></label>):<p className="hint">No other active Reference papers. In Papers, change a paper’s status to Reference to add it here.</p>}</div>
    {base&&<p className="compare-base-status">Base paper · {base.questions.length} extracted questions</p>}
    {!patterns.length&&<p className="error" role="alert">No comparison pattern with a question-to-unit layout is saved yet.</p>}{issue&&<p className="error" role="alert">{issue}</p>}
    {preview&&<div className="compare-scope-preview"><strong>{preview.checks} unit-block checks</strong><p>{preview.targets} Base questions · {preview.references} comparison questions · {preview.skipped.length} cross-unit pairs skipped.</p>{preview.pattern_issues?.length>0&&<ul>{preview.pattern_issues.slice(0,8).map((item:string,index:number)=><li key={index}>{item}</li>)}</ul>}{!preview.model_configured&&<p className="hint">{preview.model_runtime?.error||'Comparison models are not ready.'}</p>}</div>}
    <footer><button className="subtle" onClick={onClose}>Cancel</button><button className="primary" disabled={busy||!baseId||!comparisonIds.length||!patternId||Boolean(preview)||!patterns.length} onClick={onPreview}>Preview comparison</button>{preview&&<button className="primary" disabled={busy||!preview.pairs||preview.pattern_issues?.length>0||!preview.model_configured} onClick={onRun}>Run classification</button>}</footer>
  </section></div>
}

async function api<T>(path:string, options?:RequestInit):Promise<T> {
  const response = await fetch('/api'+path, {headers:{...(options?.body instanceof FormData?{}:{'Content-Type':'application/json'})}, ...options})
  if (!response.ok) {
    const error = await response.json().catch(()=>({detail:response.statusText}))
    throw new Error(typeof error.detail==='string'?error.detail:JSON.stringify(error.detail))
  }
  return response.json()
}

