  useEffect(()=>{if(!comparePickerOpen||comparePatternId)return;const patterns=templates.filter(item=>item.kind==='comparison'&&(item.definition as any)?.question_pattern?.units?.length);const preferred=patterns.find(item=>/insem-4m/i.test(item.name))||patterns[0];if(preferred)setComparePatternId(preferred.id)},[comparePickerOpen,comparePatternId,templates])
  const [materialTopic,setMaterialTopic]=useState<Record<number,string>>({})
