    const sections=template?.definition?.sections
    const slots=Array.isArray(sections)?sections.flatMap((section:any)=>Array.isArray(section?.slots)?section.slots:[]):[]
    const units=slots.map((slot:any)=>slot?.unit??generationUnit).filter((unit:any)=>Number.isInteger(unit)&&unit>=1&&unit<=5)
