  function addPatternUnit(){const units=[...(comparisonTemplateDefinition.question_pattern?.units||[])];const used=units.map((unit:any)=>unit.unit);const next=[1,2,3,4,5].find(unit=>!used.includes(unit));if(next){setQuestionPatternField('units',[...units,{unit:next,questions:[],choices:[]}]);setQuestionDrafts(old=>[...old,'']);setTemplatePreview(null)}}
