  async function deleteConversation(id:number){
    if(busy||chatBusy||deletingConversation!==null)return
    setDeletingConversation(id)
    try{
      await api('/conversations/'+id,{method:'DELETE'})
      setRecentConversations(old=>old.filter(c=>c.id!==id))
      if(conversationId===id){setConversationId(null);setMessages([{id:Date.now(),role:'assistant',text:'What would you like to work on?'}]);setDraft('')}
    }catch(e){setError(`Could not delete conversation: ${String(e)}`)}finally{setDeletingConversation(null)}
  }
  async function deleteByRequest(kind:string,target:string){const cleaned=target.replace(/^#/, '').trim();let id=Number(cleaned);if(!Number.isInteger(id)||id<=0){const matches=kind==='paper'?papers.filter(p=>p.title.toLowerCase()===cleaned.toLowerCase()):kind==='material'?materials.filter(m=>m.filename.toLowerCase()===cleaned.toLowerCase()):kind==='template'?templates.filter(t=>t.name.toLowerCase()===cleaned.toLowerCase()):paper?.questions.filter(q=>q.number.toLowerCase()===cleaned.toLowerCase())||[];if(matches.length!==1){say('assistant',`I could not identify one ${kind} named “${target}”. Use its ID or an exact name.`);return}id=matches[0].id}try{const path=kind==='paper'?'/papers/':kind==='question'?'/questions/':kind==='material'?'/materials/':'/templates/';const deletion=await api<{conversations_removed?:number[]}>(path+id,{method:'DELETE'});if(kind==='paper'){setPapers(old=>old.filter(p=>p.id!==id));setMessages(old=>old.filter(message=>message.upload?.paper?.id!==id));if(tagJob?.paper_id===id)setTagJob(null);if(selectedPaper===id)setSelectedPaper(null);const updated=await api<Comparison[]>('/comparisons');setComparisons(updated);if(selectedComparison&&!updated.some(item=>item.id===selectedComparison)){setSelectedComparison(null);setSelectedResult(null)}setRecentConversations(await api('/conversations?subject_id='+subjectId));if(conversationId&&deletion.conversations_removed?.includes(conversationId)){setConversationId(null);setMessages([{id:Date.now(),role:'assistant',text:'What would you like to work on?'}])}}if(kind==='question'){setPapers(old=>old.map(p=>({...p,questions:p.questions.filter(q=>q.id!==id)})));setComparisons(await api<Comparison[]>('/comparisons'))}if(kind==='material')setMaterials(old=>old.filter(m=>m.id!==id));if(kind==='template')setTemplates(old=>old.filter(t=>t.id!==id));say('assistant',`Deleted ${kind} ${id}. The change is final and recorded in the audit log.`)}catch(e){say('assistant',`Could not delete ${kind} ${id}: ${String(e)}`)}}
  async function stopResponse(){
    if(!activeRunId||stoppingResponse)return
    setStoppingResponse(true)
    try{await api('/chat/runs/'+activeRunId+'/stop',{method:'POST'})}
    catch(e){setStoppingResponse(false);setError(`Could not stop the response: ${String(e)}`)}
  }
  async function send(overrideText?:string){
    if(overrideText===undefined&&/^(?:\/generate\s+insem|(?:please\s+)?(?:generate|create|make)\s+(?:an?\s+)?in[ -]?sem(?:\s+(?:paper|exam))?[.!]?)$/i.test(draft.trim())){const request=draft.trim();setDraft('');say('user',request);await generateInsem();return}
    if(overrideText===undefined&&/^\/\s*generate$/i.test(draft.trim())){setDraft('');say('user','/generate');say('assistant','Choose the paper details, syllabus topics and past questions. I will try to produce more B and C results.','generate');return}
    if(overrideText===undefined&&/^\/\s*report$/i.test(draft.trim())){setDraft('');say('user','/report');say('assistant','Download the saved comparison results from this chat.','report');return}
    if(overrideText===undefined&&/^\/\s*compare$/i.test(draft.trim())){setDraft('');setCompareBaseId(papers.find(p=>p.id===selectedPaper&&!p.archived)?.id||papers.find(p=>!p.archived)?.id||null);setComparePaperIds([]);setPaperComparePreview(null);setPaperCompareIssue('');setComparePickerOpen(true);return}
    if(overrideText===undefined&&pendingAttachment&&!chatBusy){const attachment=pendingAttachment;const caption=draft.trim()||`Please review ${attachment.file.name}.`;setPendingAttachment(null);setDraft('');await uploadInChat(attachment.file,attachment.kind,caption);return}
    const text=(overrideText??draft).trim();if(!text||!subjectId||chatBusy)return
    if(overrideText===undefined)setDraft('');say('user',text);setChatBusy(true);setActiveRunId(null);setStoppingResponse(false)
    const messageId=Date.now()+Math.random()
    setMessages(old=>[...old,{id:messageId,role:'assistant',text:'',streaming:true,activity:[]}])
    let activity:Activity[]=[]
    const modelContent:Record<string,string>={}
    try{
      const reply=await streamChat<{conversation_id:number;text:string;card?:Message['card'];view?:View;file_url?:string;tool_trace?:any[];activity?:Activity[]}>({subject_id:subjectId,text,conversation_id:conversationId,comparison_id:selectedComparison,result_id:selectedResult?.id},event=>{
        if(event.event==='started'&&event.payload.run_id)setActiveRunId(event.payload.run_id)
        activity=appendActivity(activity,event)
        if(event.event==='conversation')setConversationId(event.payload.conversation_id)
        let partial=''
        if(event.event==='content'){
          const key=event.payload.request_id||'response'
          modelContent[key]=(modelContent[key]||'')+event.payload.text
          partial=answerPrefix(modelContent[key])
        }
        setMessages(old=>old.map(message=>message.id===messageId?{...message,activity:[...activity],...(partial?{text:partial}:{})}:message))
      })
      setConversationId(reply.conversation_id)
      setMessages(old=>old.map(message=>message.id===messageId?{...message,...reply,activity:reply.activity||activity,streaming:false}:message))
      if(reply.view==='papers'){const generationEvent=reply.tool_trace?.find((event:any)=>['generate_questions','suggest_replacements'].includes(event.name)&&event.result?.success);if(generationEvent)setSelectedPaper(generationEvent.result.paper_id);setPapers(await api<Paper[]>('/papers?subject_id='+subjectId))}
      if(reply.tool_trace?.some((event:any)=>event.name==='apply_material_mapping'&&event.result?.success)){setTree(await api('/subjects/'+subjectId+'/tree'));await refresh()}
      if(reply.view==='knowledge'){setTree(await api('/subjects/'+subjectId+'/tree'));setTreeRevisions(await api<TreeRevision[]>('/subjects/'+subjectId+'/tree/revisions'))}
      if(reply.view==='templates'){setTemplates(await api<Template[]>('/templates'));setTemplatePreview(null)}
      if(reply.view==='materials')setMaterials(await api<Material[]>('/materials?subject_id='+subjectId))
      if(reply.view==='reports'){
        setComparisons(await api<Comparison[]>('/comparisons'))
        const opened=reply.tool_trace?.find((event:any)=>['rerun_comparison','cancel_comparison','resume_comparison','start_comparison'].includes(event.name)&&event.result?.success)
        if(opened){setSelectedComparison(opened.result.comparison_id);setSelectedResult(null)}
        const inspected=reply.tool_trace?.find((event:any)=>event.name==='inspect_comparison_result'&&event.result?.id)
        if(inspected){
          const detail=await api<Comparison>('/comparisons/'+inspected.result.comparison_id)
          setSelectedComparison(detail.id)
          setSelectedResult(detail.results?.find(item=>item.id===inspected.result.id)||null)
          setComparisons(old=>old.map(item=>item.id===detail.id?detail:item))
        }else{
          const listed=reply.tool_trace?.find((event:any)=>event.name==='list_comparison_results'&&event.result?.comparison_id)
          if(listed){setSelectedComparison(listed.result.comparison_id);setSelectedResult(null)}
        }
        const resolved=reply.tool_trace?.find((event:any)=>event.name==='resolve_selected_result'&&event.result?.success)
        if(resolved)setSelectedResult(old=>old&&old.id===resolved.result.result_id?{...old,label:resolved.result.label,reason:resolved.result.reason,source:'faculty_case_review'}:old)
      }
      setRecentConversations(await api('/conversations?subject_id='+subjectId))
      if(/^delete\s+/i.test(text)||reply.tool_trace?.some(event=>event.name==='delete_record'&&event.result?.success)){await refresh();const [updatedPapers,updatedMaterials,updatedComparisons]=await Promise.all([api<Paper[]>('/papers?subject_id='+subjectId),api<Material[]>('/materials?subject_id='+subjectId),api<Comparison[]>('/comparisons')]);setPapers(updatedPapers);setMaterials(updatedMaterials);setComparisons(updatedComparisons);setTemplates(await api<Template[]>('/templates'));setRecentConversations(await api('/conversations?subject_id='+subjectId));if(selectedPaper&&!updatedPapers.some(item=>item.id===selectedPaper))setSelectedPaper(null);if(selectedComparison&&!updatedComparisons.some(item=>item.id===selectedComparison)){setSelectedComparison(null);setSelectedResult(null)}if(conversationId){const saved=await api<{messages:Message[]}>(`/conversations/${conversationId}`);setMessages(saved.messages)}}
    }catch(e){setMessages(old=>old.map(message=>message.id===messageId?{...message,text:'The request failed: '+String(e),streaming:false}:message))}finally{setChatBusy(false);setActiveRunId(null);setStoppingResponse(false)}
  }
  async function uploadInChat(file:File,kind:'paper'|'material'|'syllabus'|'template',caption?:string){
    if(caption===undefined){setPendingAttachment({file,kind});setDraft(current=>current.trim()?current:`Please review ${file.name}.`);return}
    if(!subjectId)return
    const text=`${caption.trim()}\n\nAttached: ${file.name}`
    say('user',text)
    const messageId=Date.now()+Math.random()
    const toolCallId=`upload-${messageId}`
    setMessages(old=>[...old,{id:messageId,role:'assistant',text:`Reading ${file.name}…`,streaming:true,activity:[{agent:'workspace',event:'tool_started',payload:{name:`upload_${kind}`,call_id:toolCallId,arguments:{filename:file.name}}}]}])
    const form=new FormData();form.append('subject_id',String(subjectId));form.append('kind',kind);form.append('file',file);form.append('message',text);if(conversationId)form.append('conversation_id',String(conversationId));if(kind==='paper'){form.append('status',paperStatus);if(paperYear)form.append('year',paperYear)}
    setBusy(true)
    try{
      const reply=await api<{conversation_id:number;text:string;view:View;tool_trace:any[];upload:any}>('/chat/upload',{method:'POST',body:form})
      if(reply.upload?.tagging_job_id&&reply.upload?.paper?.id)setTagJob({id:reply.upload.tagging_job_id,paper_id:reply.upload.paper.id,status:'queued',progress:0,total:reply.upload.paper.questions?.length||0,error:null})
      setConversationId(reply.conversation_id);setMessages(old=>old.map(message=>message.id===messageId?{...message,text:reply.text,tool_trace:reply.tool_trace,upload:reply.upload,reveal:true,streaming:false,activity:[{agent:'workspace',event:'tool',payload:{name:`upload_${kind}`,call_id:toolCallId,arguments:{filename:file.name},result:kind==='paper'?{status:reply.upload?.status||'saved',questions:reply.upload?.paper?.questions?.length||0,warnings:reply.upload?.warnings||[]}:{status:'complete'}}}]}:message));setView(kind==='material'?'chat':reply.view)
      if(reply.upload?.paper)setPapers(await api<Paper[]>('/papers?subject_id='+subjectId))
      if(reply.view==='materials')setMaterials(await api<Material[]>('/materials?subject_id='+subjectId))
      if(reply.view==='templates'){setTemplates(await api<Template[]>('/templates'));setTemplatePreview(null)}
      if(reply.view==='knowledge'){const imported=await api<Subject[]>('/subjects');setSubjects(imported);const treeSubject=imported.find(item=>item.code===subject?.code);if(treeSubject){setSubjectId(treeSubject.id);setTree(await api('/subjects/'+treeSubject.id+'/tree'))}if(kind==='syllabus'&&reply.upload?.id)setSyllabusStatus({id:reply.upload.id,filename:reply.upload.filename,subject_id:null,status:reply.upload.status,error:null,warnings:reply.upload.warnings||[],job:{id:reply.upload.job_id,status:'queued',progress:0,total:1,error:null}})}
      setRecentConversations(await api('/conversations?subject_id='+subjectId))
    }catch(e){setMessages(old=>old.map(message=>message.id===messageId?{...message,text:`Upload failed: ${String(e)}`,streaming:false,activity:[{agent:'workspace',event:'tool',payload:{name:`upload_${kind}`,call_id:toolCallId,arguments:{filename:file.name},result:{error:String(e)}}}]}:message))}finally{setBusy(false)}
  }
  async function createPaper(){if(!subjectId||!paperTitle.trim())return;setBusy(true);try{const p=await api<Paper>('/papers',{method:'POST',body:JSON.stringify({subject_id:subjectId,title:paperTitle,year:paperYear?Number(paperYear):null,status:paperStatus})});setPapers(old=>[p,...old]);setSelectedPaper(p.id);setPaperTitle('');setPaperYear('');say('assistant',`Created “${p.title}” as ${p.status}. Attach its file or add questions directly.`);setView('papers')}catch(e){setError(String(e))}finally{setBusy(false)}}
  async function upload(file:File,pid:number){setBusy(true);try{const form=new FormData();form.append('file',file);const result=await api<{paper:Paper;warnings:string[];drafted_questions:number;tagging_job_id:number|null}>('/papers/'+pid+'/upload',{method:'POST',body:form});setPapers(old=>old.map(p=>p.id===pid?result.paper:p));say('assistant',`Stored ${file.name} and extracted ${result.drafted_questions} questions.${result.tagging_job_id?` Topic analysis queued as job ${result.tagging_job_id}.`:''}${result.warnings.length?' '+result.warnings.join(' '):''} Questions without a valid topic tag remain visible and can be edited.`);setView('papers')}catch(e){setError(String(e))}finally{setBusy(false)}}
