  async function previewSelectedPapers(){setPaperCompareIssue('');setPaperComparePreview(null);if(!compareBaseId||!comparePaperIds.length){setPaperCompareIssue('Choose one Base paper and at least one comparison paper.');return}if(!comparePatternId){setPaperCompareIssue('Choose a comparison pattern to map question numbers to units.');return}try{const result=await api<any>('/comparisons/by-papers',{method:'POST',body:JSON.stringify({subject_id:subjectId,base_paper_id:compareBaseId,comparison_paper_ids:comparePaperIds,template_id:comparePatternId,preview:true})});setPaperComparePreview(result)}catch(e){setPaperCompareIssue(String(e))}}
